description:
Signed overflow is undefined behaviour, and unsigned overflow wraps silently. Code that computes sizes from untrusted numbers must detect both. Write, without using any type wider than the inputs:

- `checkedAdd(a, b)` for `std::int32_t`: the sum, or `std::nullopt` if it would overflow;
- `checkedMul(a, b)` for `std::uint64_t`: the product, or `std::nullopt` if it would exceed the maximum;
- `allocationSize(count, elementSize, header)`: `header + count * elementSize` as `std::uint64_t`, or `std::nullopt` if any step overflows.

Do not compute the overflowing result and then test it (that is already undefined for signed values). Check **before** the operation.

starter.solution.cpp:
#include <cstdint>
#include <optional>

std::optional<std::int32_t> checkedAdd(std::int32_t a, std::int32_t b) { return a + b; }
std::optional<std::uint64_t> checkedMul(std::uint64_t a, std::uint64_t b) { return a * b; }
std::optional<std::uint64_t> allocationSize(std::uint64_t count, std::uint64_t elementSize, std::uint64_t header) { return header + count * elementSize; }

solution.solution.cpp:
#include <cstdint>
#include <limits>
#include <optional>

std::optional<std::int32_t> checkedAdd(std::int32_t a, std::int32_t b)
{
    constexpr std::int32_t maxv{ std::numeric_limits<std::int32_t>::max() };
    constexpr std::int32_t minv{ std::numeric_limits<std::int32_t>::min() };
    if (b > 0 && a > maxv - b) return std::nullopt;     // would go above the maximum
    if (b < 0 && a < minv - b) return std::nullopt;     // would go below the minimum
    return a + b;
}

std::optional<std::uint64_t> checkedMul(std::uint64_t a, std::uint64_t b)
{
    if (a != 0 && b > std::numeric_limits<std::uint64_t>::max() / a) return std::nullopt;
    return a * b;
}

std::optional<std::uint64_t> allocationSize(std::uint64_t count, std::uint64_t elementSize, std::uint64_t header)
{
    const auto body{ checkedMul(count, elementSize) };
    if (!body) return std::nullopt;
    if (header > std::numeric_limits<std::uint64_t>::max() - *body) return std::nullopt;
    return header + *body;
}

unitTests:
#include <limits>
TEST("ordinary additions") { CHECK_EQ(*checkedAdd(2, 3), 5); CHECK_EQ(*checkedAdd(-2, -3), -5); }
TEST("add at the limits") { constexpr auto mx{ std::numeric_limits<std::int32_t>::max() }; constexpr auto mn{ std::numeric_limits<std::int32_t>::min() }; CHECK_EQ(*checkedAdd(mx, 0), mx); CHECK(!checkedAdd(mx, 1).has_value()); CHECK(!checkedAdd(mn, -1).has_value()); CHECK_EQ(*checkedAdd(mx, mn), -1); }
TEST("multiply") { CHECK_EQ(*checkedMul(1000, 1000), 1000000ull); CHECK_EQ(*checkedMul(0, std::numeric_limits<std::uint64_t>::max()), 0ull); CHECK(!checkedMul(1ull << 32, 1ull << 32).has_value()); CHECK_EQ(*checkedMul(1ull << 31, 1ull << 32), 1ull << 63); }
TEST("allocation sizes") { CHECK_EQ(*allocationSize(100, 24, 16), 2416ull); CHECK(!allocationSize(1ull << 62, 8, 0).has_value()); CHECK(!allocationSize(1, std::numeric_limits<std::uint64_t>::max(), 1).has_value()); }

